public List<Integer> missingNumbers(int[] reduced, int[] original) {
    Set<Integer> present = new HashSet<>();
    for (int x : reduced) present.add(x);
    TreeSet<Integer> missing = new TreeSet<>();
    for (int x : original) {
        if (!present.contains(x)) missing.add(x);
    }
    return new ArrayList<>(missing); // WRONG: ignores multiplicity
}

