public List<Integer> missingNumbers(int[] reduced, int[] original) {
    Map<Integer, Integer> countOrig = new HashMap<>();
    for (int x : original) countOrig.merge(x, 1, Integer::sum);
    Map<Integer, Integer> countRed = new HashMap<>();
    for (int x : reduced) countRed.merge(x, 1, Integer::sum);

    TreeSet<Integer> missing = new TreeSet<>();
    for (Map.Entry<Integer, Integer> e : countOrig.entrySet()) {
        if (e.getValue() > countRed.getOrDefault(e.getKey(), 0)) {
            missing.add(e.getKey());
        }
    }
    return new ArrayList<>(missing);
}

