from collections import Counter


def missing_numbers(reduced: list[int], original: list[int]) -> list[int]:
    count_orig = Counter(original)
    count_red = Counter(reduced)
    missing = [v for v in count_orig if count_orig[v] > count_red[v]]
    return sorted(missing)
